macro_rules! compare_generic_param_kinds {
    () => {
        # [doc = " Checks that all parameters in the generics of a given assoc item in a trait impl have"] # [doc = " the same kind as the respective generic parameter in the trait def."] # [doc = ""] # [doc = " For example all 4 errors in the following code are emitted here:"] # [doc = " ```rust,ignore (pseudo-Rust)"] # [doc = " trait Foo {"] # [doc = "     fn foo<const N: u8>();"] # [doc = "     type Bar<const N: u8>;"] # [doc = "     fn baz<const N: u32>();"] # [doc = "     type Blah<T>;"] # [doc = " }"] # [doc = ""] # [doc = " impl Foo for () {"] # [doc = "     fn foo<const N: u64>() {}"] # [doc = "     //~^ error"] # [doc = "     type Bar<const N: u64> = ();"] # [doc = "     //~^ error"] # [doc = "     fn baz<T>() {}"] # [doc = "     //~^ error"] # [doc = "     type Blah<const N: i64> = u32;"] # [doc = "     //~^ error"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This function does not handle lifetime parameters"] fn compare_generic_param_kinds < 'tcx > (tcx : TyCtxt < 'tcx > , impl_item : ty :: AssocItem , trait_item : ty :: AssocItem , delay : bool ,) -> Result < () , ErrorGuaranteed > { assert_eq ! (impl_item . as_tag () , trait_item . as_tag ()) ; let ty_const_params_of = | def_id | { tcx . generics_of (def_id) . own_params . iter () . filter (| param | { matches ! (param . kind , GenericParamDefKind :: Const { .. } | GenericParamDefKind :: Type { .. }) }) } ; for (param_impl , param_trait) in iter :: zip (ty_const_params_of (impl_item . def_id) , ty_const_params_of (trait_item . def_id)) { use GenericParamDefKind :: * ; if match (& param_impl . kind , & param_trait . kind) { (Const { .. } , Const { .. }) if tcx . type_of (param_impl . def_id) != tcx . type_of (param_trait . def_id) => { true } (Const { .. } , Type { .. }) | (Type { .. } , Const { .. }) => true , (Const { .. } , Const { .. }) | (Type { .. } , Type { .. }) => false , (Lifetime { .. } , _) | (_ , Lifetime { .. }) => { bug ! ("lifetime params are expected to be filtered by `ty_const_params_of`") } } { let param_impl_span = tcx . def_span (param_impl . def_id) ; let param_trait_span = tcx . def_span (param_trait . def_id) ; let mut err = struct_span_code_err ! (tcx . dcx () , param_impl_span , E0053 , "{} `{}` has an incompatible generic parameter for trait `{}`" , impl_item . descr () , trait_item . name () , & tcx . def_path_str (tcx . parent (trait_item . def_id))) ; let make_param_message = | prefix : & str , param : & ty :: GenericParamDef | match param . kind { Const { .. } => { format ! ("{} const parameter of type `{}`" , prefix , tcx . type_of (param . def_id) . instantiate_identity ()) } Type { .. } => format ! ("{prefix} type parameter") , Lifetime { .. } => span_bug ! (tcx . def_span (param . def_id) , "lifetime params are expected to be filtered by `ty_const_params_of`") , } ; let trait_header_span = tcx . def_ident_span (tcx . parent (trait_item . def_id)) . unwrap () ; err . span_label (trait_header_span , "") ; err . span_label (param_trait_span , make_param_message ("expected" , param_trait)) ; let impl_header_span = tcx . def_span (tcx . parent (impl_item . def_id)) ; err . span_label (impl_header_span , "") ; err . span_label (param_impl_span , make_param_message ("found" , param_impl)) ; let reported = err . emit_unless_delay (delay) ; return Err (reported) ; } } Ok (()) }
    };
}

compare_generic_param_kinds!();